def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separate the two panels at the uniform divider.
    sep_row = next((r for r, row in enumerate(grid)
                    if len(set(row)) == 1), None)

    if sep_row is not None:
        a, b = grid[:sep_row], grid[sep_row + 1:]
        n = min(len(a), len(b))
        a, b = a[:n], b[:n]
        height, width = n, min(len(a[0]), len(b[0]))
        get_a = lambda r, c: a[r][c]
        get_b = lambda r, c: b[r][c]
    else:
        sep_col = next((c for c in range(w)
                        if len({grid[r][c] for r in range(h)}) == 1), None)
        if sep_col is None:
            return []
        width = min(sep_col, w - sep_col - 1)
        height = h
        get_a = lambda r, c: grid[r][c]
        get_b = lambda r, c: grid[r][sep_col + 1 + c]

    # With sparse, differently colored marks on a zero background,
    # mark left-panel cells horizontally adjacent to a right-panel mark.
    vals_a = [get_a(r, c) for r in range(height) for c in range(width)]
    vals_b = [get_b(r, c) for r in range(height) for c in range(width)]
    nonzero_a = {v for v in vals_a if v != 0}
    nonzero_b = {v for v in vals_b if v != 0}
    sparse_zero = (vals_a.count(0) > len(vals_a) // 2 and
                   vals_b.count(0) > len(vals_b) // 2)

    out = [[0] * width for _ in range(height)]
    if sparse_zero and nonzero_a.isdisjoint(nonzero_b):
        for r in range(height):
            for c in range(width):
                if get_a(r, c) != 0 and (
                    (c > 0 and get_b(r, c - 1) != 0) or
                    (c + 1 < width and get_b(r, c + 1) != 0)
                ):
                    out[r][c] = 2
    else:
        for r in range(height):
            for c in range(width):
                if get_a(r, c) != 0 and get_b(r, c) != 0:
                    out[r][c] = 2
    return out
